// Flowise Custom Tool get_decision_status (generated by flowise/scinsight/build-scinsight.cjs)
// Read a recommendation with its verified human review, SAP execution record and observed outcomes.
// SCInsight allowlisted tool: GET /api/v1/decisions/{recommendation_id} (fixed endpoint; key from Flowise Variables, never from the model)
const fetch = require('node-fetch');
const base = String($vars.sci_api_url || '').replace(/\/+$/, '');
const key = String($vars.sci_agent_key || '');
if (!base || !key) return JSON.stringify({ error: 'configuration', detail: 'Flowise variables sci_api_url and sci_agent_key are required' });
const args = {};
let recommendation_id = typeof $recommendation_id === 'undefined' || $recommendation_id === null ? '' : String($recommendation_id).trim();
recommendation_id = recommendation_id.toUpperCase();
if (/^(none|null|undefined|n\/a)?$/i.test(recommendation_id)) recommendation_id = '';
if (!recommendation_id) return JSON.stringify({ error: 'invalid_argument', detail: 'recommendation_id is required' });
if (recommendation_id && !/^REC-[A-Z0-9-]{4,40}$/.test(recommendation_id)) return JSON.stringify({ error: 'invalid_argument', detail: 'recommendation_id has an invalid format: ' + recommendation_id.slice(0, 40) });
if (recommendation_id) args.recommendation_id = recommendation_id;
let url = base + "/api/v1/decisions/{recommendation_id}".replace('{recommendation_id}', encodeURIComponent(args.recommendation_id));
const options = { method: 'GET', headers: { 'X-API-Key': key, 'Content-Type': 'application/json', Accept: 'application/json' } };
let res;
try { res = await fetch(url, options); } catch (e) { return JSON.stringify({ error: 'unreachable', detail: String(e && e.message || e).slice(0, 200) }); }
const text = await res.text();
let data;
try { data = JSON.parse(text); } catch (e) { data = { detail: text.slice(0, 500) }; }
if (!res.ok) return JSON.stringify({ error: 'http_' + res.status, detail: data.detail || data });
// keep the answer inside the model context: drop record-level lineage, keep the snapshot id
const strip = (o) => Array.isArray(o) ? o.map(strip) : (o && typeof o === 'object') ? Object.fromEntries(Object.entries(o).filter(([k]) => k !== 'source_records' && k !== 'provenance').map(([k, v]) => [k, strip(v)])) : o;
const out = strip(data);
if (data && data.provenance) out.snapshot_id = data.provenance.snapshot_id;
const json = JSON.stringify(out);
return json.length > 9000 ? json.slice(0, 9000) + ' ...[truncated: call a narrower query]' : json;
